function Search() {
  const [query, setQuery] = useState('');   // для поля ввода
  const [filter, setFilter] = useState(''); // для тяжёлого списка
  const [isPending, startTransition] = useTransition();

  function handleChange(e) {
    setQuery(e.target.value);                          // срочно
    startTransition(() => setFilter(e.target.value));  // несрочно
  }

  return (
    <>
      <input value={query} onChange={handleChange} />
      <div style={{ opacity: isPending ? 0.5 : 1 }}>
        <SlowList filter={filter} />   {/* SlowList обёрнут в memo */}
      </div>
    </>
  );
}

// Реальный вывод (React 19.3, jsdom), нажатие "a":
// Search render query="a" filter="" isPending=true    <- срочный рендер, список пропущен
// Search render query="a" filter="a" isPending=false  <- фоновый рендер
//   SlowList render filter="a"

function Search() {
  const [query, setQuery] = useState('');
  const deferredQuery = useDeferredValue(query);
  return (
    <>
      <input value={query} onChange={(e) => setQuery(e.target.value)} />
      <SlowList query={deferredQuery} />   {/* memo */}
    </>
  );
}

