// Кэш: один и тот же промис на каждый рендер
const cache = new Map();
function fetchData(key) {           // каждый запрос отвечает через 100 мс
  if (!cache.has(key)) cache.set(key, delay(100, key));
  return cache.get(key);
}

// A. fetch-on-render: запрос стартует, когда до компонента дошёл рендер
function User()     { use(fetchData('user'));     return <Posts />; }
function Posts()    { use(fetchData('posts'));    return <Comments />; }
function Comments() { use(fetchData('comments')); return 'done'; }

// B. render-as-you-fetch: всё стартует заранее, вниз идут промисы
const p = { user: fetchData('u'), posts: fetchData('p'), comments: fetchData('c') };
function User2({ p })     { use(p.user);     return <Posts2 p={p} />; }
function Posts2({ p })    { use(p.posts);    return <Comments2 p={p} />; }
function Comments2({ p }) { use(p.comments); return 'done'; }

// Реальный вывод (React 19.3), время от начала рендера:
// A:   8 ms start user | 109 ms start posts | 211 ms start comments | 312 ms all rendered
// B:   1 ms start u, p, c                                          | 102 ms all rendered

